import java.io.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= 32 && c != -1);
            while (c > 32 && c != -1) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static long cappedMultiply(long a, long b, long cap) {
        if (a == 0 || b == 0) return 0;
        if (a >= cap || b >= cap || a > cap / b) return cap;
        return a * b;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = Integer.parseInt(fs.next());
        int m = Integer.parseInt(fs.next());
        int k = Integer.parseInt(fs.next());

        char[] password = fs.next().toCharArray();
        int[][] freq = new int[m][26];

        for (int i = 0; i < m; i++) {
            String word = fs.next();
            for (int j = 0; j < word.length(); j++) {
                freq[i][word.charAt(j) - 'a']++;
            }
        }

        long rank = fs.nextLong();
        long[] suffixWays = new long[m + 1];
        suffixWays[m] = 1;
        for (int i = m - 1; i >= 0; i--) {
            suffixWays[i] = cappedMultiply(suffixWays[i + 1], k, rank);
        }

        long prefixMultiplicity = 1;
        int variableIndex = 0;

        for (int i = 0; i < n; i++) {
            if (password[i] != '#') continue;

            for (int c = 0; c < 26; c++) {
                if (freq[variableIndex][c] == 0) continue;

                long block = cappedMultiply(prefixMultiplicity, freq[variableIndex][c], rank);
                block = cappedMultiply(block, suffixWays[variableIndex + 1], rank);

                if (rank > block) {
                    rank -= block;
                } else {
                    password[i] = (char) ('a' + c);
                    prefixMultiplicity = cappedMultiply(
                            prefixMultiplicity, freq[variableIndex][c], rank);
                    break;
                }
            }
            variableIndex++;
        }

        System.out.println(new String(password));
    }
}
